multilpaBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "multilpaBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "snowLatent",
                name = "multilpa",
                version = c(1,0,0),
                options = options,
                results = multilpaResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = TRUE,
                weightsSupport = 'none')
        }))

#' Multilevel LPA
#'
#' 
#' @param data .
#' @param vars .
#' @param group .
#' @param nProfiles .
#' @param nGroupClasses .
#' @param variance .
#' @param missing .
#' @param nStarts .
#' @param maxIter .
#' @param seed .
#' @param compare .
#' @param models .
#' @param run .
#' @param showModelFit .
#' @param showClassification .
#' @param showEntropy .
#' @param showProfiles .
#' @param showGroupClasses .
#' @param showComposition .
#' @param profilePlot .
#' @param compositionPlot .
#' @param plotZ .
#' @param showStarts .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$help} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$status} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$modelFit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$classification} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$entropy} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$profiles} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$groupClasses} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$composition} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$starts} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$profileFigure} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$compositionFigure} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$saveClasses} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$saveProbabilities} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$modelFit$asDF}
#'
#' \code{as.data.frame(results$modelFit)}
#'
#' @export
multilpa <- function(
    data,
    vars,
    group,
    nProfiles = 2,
    nGroupClasses = 2,
    variance = "varying",
    missing = "complete",
    nStarts = 20,
    maxIter = 1000,
    seed = 2026,
    compare = FALSE,
    models = "2/1, 3/2",
    run = FALSE,
    showModelFit = FALSE,
    showClassification = FALSE,
    showEntropy = FALSE,
    showProfiles = FALSE,
    showGroupClasses = FALSE,
    showComposition = FALSE,
    profilePlot = FALSE,
    compositionPlot = FALSE,
    plotZ = TRUE,
    showStarts = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("multilpa requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL),
            `if`( ! missing(group), group, NULL))


    options <- multilpaOptions$new(
        vars = vars,
        group = group,
        nProfiles = nProfiles,
        nGroupClasses = nGroupClasses,
        variance = variance,
        missing = missing,
        nStarts = nStarts,
        maxIter = maxIter,
        seed = seed,
        compare = compare,
        models = models,
        run = run,
        showModelFit = showModelFit,
        showClassification = showClassification,
        showEntropy = showEntropy,
        showProfiles = showProfiles,
        showGroupClasses = showGroupClasses,
        showComposition = showComposition,
        profilePlot = profilePlot,
        compositionPlot = compositionPlot,
        plotZ = plotZ,
        showStarts = showStarts)

    analysis <- multilpaClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

